50 | /// @title A simple on-chain price oracle mechanism
51 | /// @author github.com/drbh,github.com/yrong
52 | /// @notice Offchain clients can update the prices in this contract. The public can read prices
53 | /// aggeregate prices which are not expired from different feeders, if number of valid/unexpired prices
54 | /// not enough, we do not aggeregate and just use previous price
55 | contract NFTFloorOracle is Initializable, AccessControl, INFTFloorOracle {
56 |     event AssetAdded(address indexed asset);
57 |     event AssetRemoved(address indexed asset);
58 |     event AssetPaused(address indexed asset, bool paused);
59 | 
60 |     event FeederAdded(address indexed feeder);
61 |     event FeederRemoved(address indexed feeder);
62 | 
63 |     event OracleConfigSet(uint128 expirationPeriod, uint128 maxPriceDeviation);
64 |     event AssetDataSet(
65 |         address indexed asset,
66 |         uint256 twap,
67 |         uint256 lastUpdatedBlock
68 |     );
